-- BET-62 (complément) : carte joueur personnalisée, effets de victoire et ambiances sonores. Après V16, réexécutable, sans effet sur les inventaires existants.
-- Fonds, polices du numéro et effets de carte sont visibles de tous avec la carte (vue public_equipped) ; effets de victoire et sons ne se jouent que chez leur propriétaire (equipped_items, lecture par le propriétaire).
begin;
create or replace view public.public_equipped as
select e.user_id, e.slot, e.item_id, i.name, i.asset from public.equipped_items e join public.shop_items i on i.id = e.item_id where e.slot in ('title','frame','cardbg','cardfont','cardfx');
grant select on table public.public_equipped to anon, authenticated;
-- Catalogue : prix et règles identiques à shop.js. Les inventaires et les équipements ne sont pas modifiés.
insert into public.shop_items(id,category,name,rarity,price,exclusive,min_division,collection,asset,pack_of)
select id,category,name,rarity,price,exclusive,min_division,collection,asset,pack_of from jsonb_to_recordset($catalog$[{"id":"cardbg-pitch","category":"cardbg","name":"Fond pelouse","rarity":"common","price":600,"exclusive":false,"min_division":null,"collection":null,"asset":"pitch","pack_of":null},{"id":"cardbg-night","category":"cardbg","name":"Fond nuit de match","rarity":"common","price":700,"exclusive":false,"min_division":null,"collection":null,"asset":"night","pack_of":null},{"id":"cardbg-aurora","category":"cardbg","name":"Fond aurore","rarity":"rare","price":1800,"exclusive":false,"min_division":null,"collection":null,"asset":"aurora","pack_of":null},{"id":"cardbg-gold","category":"cardbg","name":"Fond or","rarity":"epic","price":5500,"exclusive":false,"min_division":null,"collection":null,"asset":"gold","pack_of":null},{"id":"cardfont-serif","category":"cardfont","name":"Numéro à empattements","rarity":"common","price":400,"exclusive":false,"min_division":null,"collection":null,"asset":"serif","pack_of":null},{"id":"cardfont-mono","category":"cardfont","name":"Numéro machine","rarity":"common","price":500,"exclusive":false,"min_division":null,"collection":null,"asset":"mono","pack_of":null},{"id":"cardfont-slant","category":"cardfont","name":"Numéro penché","rarity":"rare","price":1500,"exclusive":false,"min_division":null,"collection":null,"asset":"slant","pack_of":null},{"id":"cardfont-impact","category":"cardfont","name":"Numéro affiche","rarity":"rare","price":1600,"exclusive":false,"min_division":null,"collection":null,"asset":"impact","pack_of":null},{"id":"cardfx-shine","category":"cardfx","name":"Reflet","rarity":"rare","price":1800,"exclusive":false,"min_division":null,"collection":null,"asset":"shine","pack_of":null},{"id":"cardfx-sparkle","category":"cardfx","name":"Étincelles","rarity":"rare","price":2400,"exclusive":false,"min_division":null,"collection":null,"asset":"sparkle","pack_of":null},{"id":"cardfx-holo","category":"cardfx","name":"Brillant holographique","rarity":"epic","price":6500,"exclusive":false,"min_division":null,"collection":null,"asset":"holo","pack_of":null},{"id":"victoryfx-confetti","category":"victoryfx","name":"Confettis aux couleurs du club","rarity":"rare","price":1500,"exclusive":false,"min_division":null,"collection":null,"asset":"confetti","pack_of":null},{"id":"victoryfx-smoke","category":"victoryfx","name":"Fumigènes aux couleurs du club","rarity":"rare","price":2200,"exclusive":false,"min_division":null,"collection":null,"asset":"smoke","pack_of":null},{"id":"sound-siren","category":"sound","name":"Sirène de but","rarity":"common","price":800,"exclusive":false,"min_division":null,"collection":null,"asset":"siren","pack_of":null},{"id":"sound-chants","category":"sound","name":"Chants de tribune","rarity":"rare","price":2000,"exclusive":false,"min_division":null,"collection":null,"asset":"chants","pack_of":null}]$catalog$::jsonb) as r(id text,category text,name text,rarity text,price integer,exclusive boolean,min_division integer,collection text,asset text,pack_of jsonb)
on conflict(id) do update set name=excluded.name,price=excluded.price,rarity=excluded.rarity,asset=excluded.asset;
notify pgrst, 'reload schema';
commit;
